<script setup>
import {computed,inject,ref} from 'vue';
import {agentReportKey} from '../../../lib/cc-agent-report-context';
import {printReportTable} from '../../../lib/cc-report-print';
import {marketingReport} from '../../../lib/cc-marketing-report';
import {branchOf,downloadCsv} from '../../../lib/cc';
import CRMSourceSelect from '../CRMSourceSelect.vue';
import CCDataTable from '../CCDataTable.vue';
const {financial,financialLoading,financialError,applied,loadFinancial,openLead,printReport}=inject(agentReportKey);
const agencies=ref([]),category=ref(''),branch=ref(''),query=ref(''),detail=ref(null),detailTitle=ref('');
const all=computed(()=>financial.value?.rows||[]);
const choices=field=>[...new Set(all.value.map(r=>field==='branch'?branchOf(r):r[field]||'Unspecified'))].sort();
const report=computed(()=>marketingReport(financial.value,applied.value||{}, {agencies:agencies.value,category:category.value,branch:branch.value,query:query.value}));
const metrics=[['raw','Raw Leads'],['quality','Quality Leads'],['junk','Junk Leads'],['connected','Connected'],['appointments','Appointments'],['visits','Visits / Walk-ins'],['booked','Booked'],['unbooked','Unbooked'],['paid','Paid Amount'],['outstanding','Outstanding Collected Amount'],['average','Avg Ticket Price'],['leadVisit','Lead → Walk-in %'],['conversion','Walk-in → Booked %']];
const baseColumns=[{key:'name',label:'Lead Source'},...['raw','quality','junk','connected','appointments','visits','booked','unbooked','conversion','spend','paid'].map(key=>({key,label:metrics.find(x=>x[0]===key)?.[1]||(key==='spend'?'Spend':key)}))];
const categoryColumns=[{key:'name',label:'Enquired For'},...['adSets','raw','quality','junk','connected','appointments','pending','visits','booked','unbooked','leadVisit','conversion','spend','paid','average'].map(key=>({key,label:metrics.find(x=>x[0]===key)?.[1]||({adSets:'Ad Sets',pending:'Pending Appt'})[key]}))];
const combined={key:'bookedUnbooked',label:'Booked / Unbooked',value:r=>r.booked+' / '+r.unbooked};
const metricColumn=key=>baseColumns.find(c=>c.key===key)||{key,label:key};
const sections=[{key:'agency',title:'📣 Marketing Agency Summary',columns:[baseColumns[0],...['raw','quality','junk','connected','appointments','visits'].map(metricColumn),combined,...['conversion','spend','paid'].map(metricColumn)]},{key:'campaign',title:'🎯 Ad Set-wise Lead Report',columns:[{key:'name',label:'Ad Set'},{key:'enquiredFor',label:'Enquired For'},...['raw','quality','junk','connected','appointments','visits'].map(metricColumn),combined,metricColumn('conversion')]},{key:'category',title:'🗂 Category Summary',columns:categoryColumns},{key:'campaign',title:'💰 Campaign Performance',columns:[{key:'name',label:'Ad Set / Campaign Dates',value:r=>r.name+(r.start||r.end?'\n'+r.start+' → '+r.end:'')},{key:'status',label:'Status'},...['raw','quality','visits','booked','unbooked','paid'].map(metricColumn),{key:'average',label:'Avg Paid / Booked'},{key:'branchRatios',label:'Branch Conversion Ratio'}]}];
function showGroup(section,row,column){const key=column.key,field={agency:'source',campaign:'ad_set',category:'enquired_for'}[section.key];const base=['paid','average'].includes(key)?report.value.payments:key==='bookedUnbooked'?[...report.value.booked,...report.value.unbooked]:['conversion','leadVisit'].includes(key)?report.value.visits:report.value[key]||report.value.received;detailTitle.value=column.label+' · '+row.name;detail.value=base.filter(r=>row.name==='TOTAL'||String(r[field]||'Unspecified')===row.name);}

const leadColumns=[{key:'name',label:'Lead ID'},{key:'lead_name',label:'Client'},{key:'source',label:'Lead Source'},{key:'ad_set',label:'Ad Set'},{key:'enquired_for',label:'Enquired For'},{key:'branch',label:'Branch',value:branchOf},{key:'status',label:'Status'}];
const paymentColumns=[{key:'invoice',label:'Invoice'},{key:'invoice_date',label:'Invoice Date'},{key:'payment_entry',label:'Payment Entry'},{key:'payment_date',label:'Paid Date'},{key:'lead_name',label:'Client'},{key:'branch',label:'Branch'},{key:'paid',label:'Paid Amount'}];
function reset(){agencies.value=[];category.value='';branch.value='';query.value='';}
function showMetric(key,label){detailTitle.value=label;detail.value=key==='outstanding'?report.value.payments.filter(r=>r.is_later_collection):['paid','average'].includes(key)?report.value.payments:['conversion','leadVisit'].includes(key)?report.value.visits:(report.value[key]||report.value.received);}
const money=value=>'₹'+Number(value||0).toLocaleString('en-IN',{maximumFractionDigits:2});
</script>
<template><section class="life-mkt-root"><header class="life-mkt-hero"><div class="life-mkt-hero-icon">📣</div><div class="life-mkt-hero-copy"><h2>Lead &amp; Digital Marketing Report</h2><p>Lead Source-wise · Ad Set-wise · Enquired For-wise · Branch conversion</p></div><div class="life-mkt-hero-actions"><span class="life-mkt-live"><i/> LIVE ERPNext DATA</span><button class="life-mkt-btn secondary" @click="printReport">🖨 Print / PDF</button></div></header>
<div class="life-mkt-filter-wrap"><div class="life-mkt-filter"><label class="life-mkt-field">Marketing Agency<CRMSourceSelect v-model="agencies" :options="choices('source')" label="Marketing Agency"/></label><label class="life-mkt-field">Category<select v-model="category"><option value="">All Categories</option><option v-for="c in choices('enquired_for')" :key="c">{{c}}</option></select></label><label class="life-mkt-field">Branch<select v-model="branch"><option value="">All Branches</option><option v-for="b in choices('branch')" :key="b">{{b}}</option></select></label><label class="life-mkt-field">Search — client / campaign / agency<input v-model="query" placeholder="Type to search…"></label><button class="life-mkt-btn secondary" @click="reset">Reset</button></div></div>
<p v-if="financialLoading" role="status">Loading report data…</p><p v-if="financialError" role="alert">{{financialError}} <button @click="loadFinancial">Retry</button></p>
<template v-if="financial"><div class="life-mkt-kpis"><button v-for="[key,label] in metrics" :key="key" class="life-mkt-kpi" @click="showMetric(key,label)"><b class="num">{{['paid','outstanding','average'].includes(key)?money(report.totals[key]):report.totals[key]}}{{['leadVisit','conversion'].includes(key)?'%':''}}</b><span>{{label}}</span></button></div>
<div class="life-mkt-branch-strip"><b>Branch Conversion Ratio (Booked / Walk-ins)</b><div class="life-mkt-branches"><span v-for="b in report.branches" :key="b.name" class="life-mkt-branch"><strong>{{b.name}}</strong> {{b.conversion}}% ({{b.booked}}/{{b.visits}})</span></div></div>
<details v-for="(section,index) in sections" :key="index" open class="life-mkt-section"><summary class="life-mkt-section-head"><h3>{{section.title}}<small v-if="index===3"> · {{report.campaign.length}} Ad Sets</small></h3></summary><div class="life-mkt-section-body"><CCDataTable :columns="section.columns" :rows="[...report[section.key],{name:'TOTAL',...report.totals}]"><template v-for="column in section.columns.filter(c=>!['name','enquiredFor','status','spend','branchRatios'].includes(c.key))" :key="column.key" #[`cell-${column.key}`]="{row}"><button class="life-mkt-detail-count" @click="showGroup(section,row,column)">{{column.value?column.value(row):row[column.key]}}</button></template></CCDataTable><button class="life-mkt-btn secondary" @click="printReportTable(section.title,section.columns,[...report[section.key],{name:'TOTAL',...report.totals}])">🖨 Print / PDF</button><button class="life-mkt-btn secondary" @click="downloadCsv('marketing-'+section.key+'.csv',section.columns,report[section.key])">⬇ Export Excel / CSV</button></div></details>
<p class="life-mkt-category-rules">Raw = Leads received in selected period · Quality = Raw excluding Junk · Visits use explicit visited outcomes · Appointment Status takes priority over CC Sub Status · Paid Amount uses payment dates.</p></template>
<dialog :open="detail!==null" class="cc-report-dialog cc-marketing-details"><header><h2>{{detailTitle}}</h2><button @click="detail=null">Close</button></header><CCDataTable :columns="/Paid|Ticket/.test(detailTitle)?paymentColumns:leadColumns" :rows="detail||[]"><template #actions="{row}"><button v-if="row.name&&!row.invoice" @click="openLead(row.name)">Open lead</button></template></CCDataTable></dialog>
</section></template>
<style scoped src="../../../styles/cc-agent-report.css"></style>
<style scoped>.cc-marketing-details{position:fixed;inset:10vh auto auto 50%;transform:translateX(-50%);z-index:1000;box-shadow:0 0 0 100vmax #102c2266}.life-mkt-kpi{text-align:left;font:inherit;cursor:pointer}.life-mkt-field{display:grid;gap:6px}summary{cursor:pointer;list-style:none}</style>

<style scoped>.life-mkt-detail-count{border:0;background:transparent;padding:0;font:inherit;color:#146b31;text-decoration:underline;cursor:pointer}.life-mkt-section :deep(td){white-space:pre-line}</style>
